data.query:
query Query($where: MasterDataFlowConfigurationWhereInput, $orderBy: [MasterDataFlowConfigurationOrderByInput!], $first: Int, $after: String) {
  masterDataFlowConfiguration(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        dataFlowConfiguration
        topicPrefix
      }
    }
  }
}

data.transform:
$throw(
  "The requested Master Data Flow Configuration: " & $state.context.CONSTANTS.PARAMETERS.MASTER_DATA_FLOW_CONFIG_ID & " was not found.",
  {
    "info": $state.context
  }
)

data.query:
query Query($where: TopicWhereInput, $orderBy: [TopicOrderByInput!], $first: Int, $after: String) {
  topic(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        name
      }
    }
  }
}

data.variablesTransform:
{
  "payload": [
    [
      $[type = "starting"].{
        "where": {
          "name": topicString
        },
        "create": {
          "name": topicString,
          "description": "Topic used for the " & $upperFirst($split(flowConfig.dataFlow.id,"From")[0]) & " import.",
          "valueSchema": {}
        },
        "update": {
          "description": "Topic used for the " & $upperFirst($split(flowConfig.dataFlow.id,"From")[0]) & " import."
        }
      },
      $[type = "pagination"].{
        "where": {
          "name": topicString
        },
        "create": {
          "name": topicString,
          "description": "Topic used for pagination in the " & $upperFirst($split(flowConfig.dataFlow.id,"From")[0]) & " import.",
          "valueSchema": {}
        },
        "update": {
          "description": "Topic used for pagination in the " & $upperFirst($split(flowConfig.dataFlow.id,"From")[0]) & " import."
        }
      }
    ]
  ]~>$flatten
}

